

select * from customer limit 20

--01.what is the total number of revenue generated by male vs. female customer?
select gender,sum(purchase_amount) as revenue from customer group by gender;

--02.Which customer used a discount but still spent more than the average purchase amount?
select customer_id, purchase_amount
from customer
where discount_applied = 'Yes' and purchase_amount >= (select avg(purchase_amount) from customer);

--03.which are the top 5 products with the highest average review rating
select item_purchased, ROUND(avg(review_rating :: numeric),2) as "Average Product Rating" from customer 
group by item_purchased 
order by "Average Product Rating" desc
limit 5;

--04.Compared the average purchase amounts between standard and express Shipping
select shipping_type, ROUND(Avg(purchase_amount),2)
from customer
where shipping_type in('Standard','Express')
group by shipping_type;

--05.Do subscribed customer spend more? compare average spend  and total revenue 
--between subscribers and non-subscribers
select subscription_status , COUNT(customer_id) as total_customer, 
ROUND(avg(purchase_amount),2) as avg_spend, 
sum(purchase_amount) as total_revenue from customer 
group by subscription_status
order by total_revenue , avg_spend desc;

--06.which five products have the highest percentage of purchases with discounts appied?
SELECt item_purchased, 
ROUND(100 * SUM(CASE WHEN discount_applied = 'Yes' THEN 1 ELSE 0 END ) / COUNT(*) ,2) as discount_rate 
from customer 
group by item_purchased
order by discount_rate desc
limit 5;

--07. Segment  customer  into New, Returning and loyal based on their total 
--number of previous purchases and show the count of each segment.
with customer_type as (
SELECT customer_id, previous_purchases,
CASE 
    WHEN previous_purchases = 1 THEN 'New'
    WHEN previous_purchases BETWEEN 2 AND 10 THEN 'Returning'
    ELSE 'Loyal'
    END AS customer_segment
FROM customer)

select customer_segment,count(*) AS "Number of Customers" 
from customer_type 
group by customer_segment;

--Q8. What are the top 3 most purchased products within each category? 
WITH item_counts AS (
    SELECT category,
           item_purchased,
           COUNT(customer_id) AS total_orders,
           ROW_NUMBER() OVER (PARTITION BY category ORDER BY COUNT(customer_id) DESC) AS item_rank
    FROM customer
    GROUP BY category, item_purchased
)
SELECT item_rank,category, item_purchased, total_orders
FROM item_counts
WHERE item_rank <=3;
 
--Q9. Are customers who are repeat buyers (more than 5 previous purchases) also likely to subscribe?
SELECT subscription_status,
       COUNT(customer_id) AS repeat_buyers
FROM customer
WHERE previous_purchases > 5
GROUP BY subscription_status;

--Q10. What is the revenue contribution of each age group? 
SELECT 
    age_group,
    SUM(purchase_amount) AS total_revenue
FROM customer
GROUP BY age_group
ORDER BY total_revenue desc;